// Importing React and useEffect
import React, { useEffect } from 'react';

// Defining a custom hook called useFetch
function useFetch(url) {
  // Setting up state for the data and loading status
  const [data, setData] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  // Defining a function to fetch the data from the given url
  async function fetchData() {
    const response = await fetch(url);
    const json = await response.json();
    setData(json.results);
    setLoading(false);
  }

  // Fetching the data when the url changes
  useEffect(() => {
    fetchData();
  }, [url]);

  // Returning the data and loading status
  return { data, loading };
}

// Exporting the useFetch hook as the default export
export default useFetch;
